[CmdletBinding()]param([Parameter(Mandatory=$true)][string]$RollbackDirectory)
$ErrorActionPreference="Stop";Set-StrictMode -Version Latest
try{$rollback=[IO.Path]::GetFullPath($RollbackDirectory);$planPath=Join-Path $rollback "transaction-plan.json";if(-not(Test-Path $planPath -PathType Leaf)){throw"plan"};$plan=Get-Content $planPath -Raw|ConvertFrom-Json;if($plan.schemaVersion-ne1-or$plan.purpose-cne"hase-minipc-python-provisioning-transaction"){throw"plan"};$entries=@($plan.entries);foreach($entry in $entries){if($entry.existed){if(-not(Test-Path $entry.path -PathType Leaf)-or(Get-FileHash $entry.path -Algorithm SHA256).Hash.ToLowerInvariant()-cne[string]$entry.sha256){throw"state"}}elseif(Test-Path $entry.path){throw"publication-state"}};$template=[string]$plan.sourceProfilePath;if(-not(Test-Path $template -PathType Leaf)){throw"template"};Remove-Item $template -Force;Remove-Item $rollback -Recurse -Force;Write-Host "Publication state unchanged: True";Write-Host "Profile template removed    : True";Write-Host "Rollback evidence removed   : True";Write-Host "Preparation recovery complete: True"}catch{Write-Error "MiniPC Python provisioning preparation recovery failed.";exit 1}
